        let ds = dCharlie(NdotH, 0.42);
        let graze = 0.16 + 0.84 * pow(1.0 - NdotV, 2.0);
        let sheenLobe = min(ds * vAshikhmin(NdotV, max(NdotL, 1e-4)) * NdotL, 0.25);
